{
  "title": "Discussion on taxes, domain purchase, and app idea",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing workaround",
      "claims": [
        {
          "text": "Paying aunt Svetlana 500 UAH helped avoid a huge amount of headache from mis‑marked columns in the tax declaration.",
          "evidence": [1]
        },
        {
          "text": "The inspector approved the declarations without looking for a year and later demanded a full re‑check, but connections allowed the declarations to be corrected for about 1 000 UAH instead of paying all fines.",
          "evidence": [1]
        },
        {
          "text": "The whole procedure takes about an hour with Excel, at most a day.",
          "evidence": [5, 6]
        },
        {
          "text": "Quarterly reports must be filed correctly and on time.",
          "evidence": [7]
        },
        {
          "text": "Mistakes often come from mis‑identifying which column to subtract which number from.",
          "evidence": [8]
        },
        {
          "text": "The calculator works only with a hryvnia‑based FOP; other currencies require conversion based on the day's exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Buying a domain",
      "claims": [
        {
          "text": "Someone needs to buy a calculator before there will be money for a domain.",
          "evidence": [4]
        },
        {
          "text": "User P4 refuses to buy the domain, calling it a cheap thing that won’t pay off.",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a web/app product",
      "claims": [
        {
          "text": "Web is the simplest platform but far less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO is weak; even on page 10 of Google the site is not found.",
          "evidence": [11]
        },
        {
          "text": "No external traffic from social networks or contextual ads; app stores promote new apps better.",
          "evidence": [11]
        },
        {
          "text": "No passive ad revenue on a website.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because a paywall appears within the first 10 seconds.",
          "evidence": [11]
        },
        {
          "text": "Conversion is assumed to be zero; the product does not simplify tasks or integrate with banks/payment cabinets.",
          "evidence": [11]
        },
        {
          "text": "Successful examples use fast delivery (under a week) and cross‑platform stacks like Flutter, copying popular ideas and tweaking them.",
          "evidence": [12]
        }
      ]
    },
    {
      "id": "pricing-model",
      "title": "Pricing and source code concerns",
      "claims": [
        {
          "text": "Before any development, it must be verified that at least ten people are willing to pay 299 UAH.",
          "evidence": [20]
        },
        {
          "text": "The source code might contain a hard‑coded promo code for 100 % discount stored in local storage.",
          "evidence": [20]
        },
        {
          "text": "User asks if the source code can be found by searching for the password.",
          "evidence": [21]
        },
        {
          "text": "Another user jokes they didn’t pay 299 UAH for it.",
          "evidence": [22]
        }
      ]
    },
    {
      "id": "app-security",
      "title": "Security and perception of the app",
      "claims": [
        {
          "text": "The app is positioned as a local‑first application with USD/UAH rate refreshed every 5 minutes and calculations done instantly in the browser.",
          "evidence": [29]
        },
        {
          "text": "Participants suspect the bundle contains hidden paid features and call the project a scam.",
          "evidence": [30, 32, 33, 34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Can the source code be found by searching for the password?",
      "evidence": [21]
    }
  ]
}
